import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';
import '../../../../l10n/gen/app_localizations.dart';

class CareReadinessPage extends StatefulWidget { const CareReadinessPage({required this.appointmentId,super.key}); final String appointmentId; @override State<CareReadinessPage> createState()=>_CareReadinessPageState(); }
class _CareReadinessPageState extends State<CareReadinessPage>{ final checked=<int>{}; @override Widget build(BuildContext c){final l=AppLocalizations.of(c);final items=[l.readinessReason,l.readinessMedications,l.readinessQuestions,l.readinessDocuments];final done=checked.length;return Scaffold(appBar:AppBar(title:Text(l.readinessTitle)),body:ListView(padding:const EdgeInsetsDirectional.all(20),children:[_Hero(done:done,total:items.length,title:l.readinessHeroTitle,subtitle:l.readinessHeroSubtitle),const SizedBox(height:18),Text(l.readinessChecklistTitle,style:Theme.of(c).textTheme.titleLarge),const SizedBox(height:8),...List.generate(items.length,(i)=>Card(child:CheckboxListTile(value:checked.contains(i),onChanged:(v)=>setState(()=>v==true?checked.add(i):checked.remove(i)),secondary:CircleAvatar(child:Text('${i+1}')),title:Text(items[i]),subtitle:Text(l.readinessChecklistHint),controlAffinity:ListTileControlAffinity.trailing))),const SizedBox(height:16),FilledButton.icon(onPressed:done==items.length?()=>c.pop():null,icon:const Icon(Icons.check_circle_outline),label:Text(l.readinessComplete))]));}}
class _Hero extends StatelessWidget { const _Hero({required this.done,required this.total,required this.title,required this.subtitle}); final int done,total; final String title,subtitle; @override Widget build(BuildContext c)=>Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(borderRadius:BorderRadius.circular(28),gradient:const LinearGradient(colors:[Color(0xff0B6E69),Color(0xff49B7A8)])),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:Theme.of(c).textTheme.headlineSmall?.copyWith(color:Colors.white,fontWeight:FontWeight.w800)),const SizedBox(height:8),Text(subtitle,style:Theme.of(c).textTheme.bodyMedium?.copyWith(color:Colors.white70)),const SizedBox(height:18),LinearProgressIndicator(value:total==0?0:done/total,minHeight:8,backgroundColor:Colors.white24,color:Colors.white,borderRadius:BorderRadius.circular(8)),const SizedBox(height:8),Text('$done / $total',style:const TextStyle(color:Colors.white,fontWeight:FontWeight.bold))]));}
